/* SmartLearn Native Color Classes */
.sl-text-primary { color: var(--smartlearn-primary) !important; }
.sl-text-emphasis { color: var(--smartlearn-text) !important; }
.sl-text-muted { color: var(--smartlearn-text-muted) !important; }
.sl-bg-main { background-color: var(--smartlearn-bg) !important; }
.sl-bg-card { background-color: var(--smartlearn-card-bg) !important; border: 1px solid var(--smartlearn-card-border) !important; }
.sl-bg-primary { background-color: var(--smartlearn-primary) !important; }
.sl-hero-bento .sl-bg-primary-subtle { background-color: color-mix(in srgb, var(--smartlearn-primary) 15%, transparent) !important; }
.sl-hero-bento .sl-btn-primary { background-color: var(--smartlearn-primary) !important; border-color: var(--smartlearn-primary) !important; color: #fff !important; }
.sl-hero-bento .sl-btn-primary:hover { background-color: var(--smartlearn-primary-hover, var(--smartlearn-primary)) !important; filter: brightness(0.9); }
.sl-hero-bento .sl-btn-outline-primary { border-color: var(--smartlearn-primary) !important; color: var(--smartlearn-primary) !important; }
.sl-hero-bento .sl-btn-outline-primary:hover { background-color: var(--smartlearn-primary) !important; color: #fff !important; }
.sl-border-primary { border-color: var(--smartlearn-primary) !important; }
.sl-hero-bento .sl-bento-title {
    letter-spacing: -0.03em;
}
.sl-hero-bento .fw-black {
    font-weight: 900;
}
.sl-hero-bento .sl-bento-card {
    transition: transform 0.3s ease, box-shadow 0.3s ease;
}
.sl-hero-bento .sl-bento-card:hover {
    transform: translateY(-5px);
    box-shadow: 0 20px 40px rgba(0,0,0,0.08) !important;
}
.sl-hero-bento .object-fit-cover {
    object-fit: cover;
}
.sl-hero-bento .transition-transform {
    transition: transform 0.5s ease;
}
.sl-hero-bento .group-hover:hover .transition-transform {
    transform: scale(1.05);
}
.sl-hero-bento .sl-play-btn {
    transition: transform 0.2s ease;
}
.sl-hero-bento .group-hover:hover .sl-play-btn {
    transform: scale(1.1);
}
.sl-hero-bento .sl-bento-hover:hover {
    background-color: transparent;
    color: var(--smartlearn-primary);
}

/* Staggered entrance animation */
.sl-hero-bento .sl-stagger-1,
.sl-hero-bento .sl-stagger-2,
.sl-hero-bento .sl-stagger-3,
.sl-hero-bento .sl-stagger-4,
.sl-hero-bento .sl-stagger-5 {
    opacity: 0;
    transform: translateY(20px);
    animation: slBentoFade 0.6s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}
.sl-hero-bento .sl-stagger-1 { animation-delay: 0.1s; }
.sl-hero-bento .sl-stagger-2 { animation-delay: 0.2s; }
.sl-hero-bento .sl-stagger-3 { animation-delay: 0.3s; }
.sl-hero-bento .sl-stagger-4 { animation-delay: 0.4s; }
.sl-hero-bento .sl-stagger-5 { animation-delay: 0.5s; }

@keyframes slBentoFade {
    to { opacity: 1; transform: translateY(0); }
}

@media (max-width: 991px) {
    .sl-hero-bento .w-75 { width: 100% !important; }
}

js:
(function() {
    const root = document.querySelector('.sl-hero-bento');
    if (!root) return;
    const playBtn = root.querySelector('.sl-play-btn');
    if (playBtn) {
        playBtn.addEventListener('click', (e) => {
            if (document.body.classList.contains('sl-editor-mode')) return;
            e.preventDefault();
            const card = playBtn.closest('.sl-bento-card');
            const urlEl = root.querySelector('.sl-item-video-url');
            const videoUrl = urlEl ? urlEl.innerText.trim() : 'https://www.youtube.com/embed/dQw4w9WgXcQ';
            if (!card || !videoUrl) return;

            const poster = card.querySelector('img');
            const overlay = playBtn.closest('.position-absolute');
            if (poster) poster.style.display = 'none';
            if (overlay) overlay.style.display = 'none';

            const oldIframe = card.querySelector('iframe');
            if (oldIframe) oldIframe.remove();

            const iframe = document.createElement('iframe');
            iframe.src = videoUrl + (videoUrl.includes('?') ? '&' : '?') + 'autoplay=1';
            iframe.style.position = 'absolute';
            iframe.style.top = '0';
            iframe.style.left = '0';
            iframe.style.width = '100%';
            iframe.style.height = '100%';
            iframe.style.minHeight = '220px';
            iframe.style.border = 'none';
            iframe.style.zIndex = '10';
            iframe.setAttribute('allow', 'accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share');
            iframe.setAttribute('allowfullscreen', 'true');
            card.appendChild(iframe);
        });
    }
})();
